'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { ModeSwitch } from '../../components/ModeSwitch';
import { Chat } from '../../components/Chat';
import { ConversationMessage, DemoActor } from '../../lib/types';
import { getDemoActors, createDemoSession, getCurrentSession } from '../../lib/backend';
import { useRealtime } from '../../lib/realtime';

export default function ChatPage() {
  const [actors, setActors] = useState<DemoActor[]>([]);
  const [selectedActor, setSelectedActor] = useState('demo-customer-1');
  const [isConnecting, setIsConnecting] = useState(false);
  const [sessionRole, setSessionRole] = useState<string | null>(null);

  const [messages, setMessages] = useState<ConversationMessage[]>([]);
  const [currentThreadId, setCurrentThreadId] = useState<string | null>(null);
  const [isTyping, setIsTyping] = useState(false);
  const [systemAlert, setSystemAlert] = useState<string | null>(null);
  const [problemAlert, setProblemAlert] = useState<string | null>(null);

  const streamingMsgIdRef = useRef<string | null>(null);
  const streamingTextRef = useRef<string>('');
  const hasInitializedRef = useRef(false);

  const onSnapshot = useCallback((snapshot: any) => {
    if (snapshot?.threadId) {
      setCurrentThreadId(snapshot.threadId);
    }
    if (Array.isArray(snapshot?.messages)) {
      setMessages((prev) => {
        // Merge snapshot.messages with prev, preserving user typed text if snapshot content is sanitized
        return snapshot.messages.map((sMsg: ConversationMessage, idx: number) => {
          if (sMsg.role === 'customer' && sMsg.content?.includes('[Mensaje de cliente recibido')) {
            const localMatch = prev[idx] || prev.find((m) => m.messageId === sMsg.messageId);
            if (localMatch && localMatch.content && !localMatch.content.includes('[Mensaje de cliente recibido')) {
              return { ...sMsg, content: localMatch.content };
            }
          }
          return sMsg;
        });
      });
    }
  }, []);

  const onStateChange = useCallback(({ status }: { status: string }) => {
    if (status === 'generating' || status === 'deciding' || status === 'normalizing' || status === 'queued') {
      setIsTyping(true);
    } else if (status === 'completed' || status === 'pending_approval' || status === 'failed') {
      setIsTyping(false);
    }
  }, []);

  const onDelta = useCallback(({ messageId, value }: { messageId: string; value: string }) => {
    setIsTyping(true);
    if (streamingMsgIdRef.current !== messageId) {
      streamingMsgIdRef.current = messageId;
      streamingTextRef.current = value;
      setMessages((prev) => {
        if (prev.some((m) => m.messageId === messageId)) {
          return prev.map((m) => (m.messageId === messageId ? { ...m, content: value } : m));
        }
        return [
          ...prev,
          {
            messageId,
            role: 'assistant',
            content: value,
            attachments: [],
            createdAt: new Date().toISOString(),
          },
        ];
      });
    } else {
      streamingTextRef.current += value;
      const updatedContent = streamingTextRef.current;
      setMessages((prev) =>
        prev.map((m) => (m.messageId === messageId ? { ...m, content: updatedContent } : m))
      );
    }
  }, []);

  const onCompleted = useCallback(({ response }: { response: string }) => {
    setIsTyping(false);
    if (streamingMsgIdRef.current) {
      const msgId = streamingMsgIdRef.current;
      setMessages((prev) =>
        prev.map((m) => (m.messageId === msgId ? { ...m, content: response } : m))
      );
    } else {
      setMessages((prev) => {
        if (prev.some((m) => m.content === response)) return prev;
        return [
          ...prev,
          {
            messageId: `completed-${Date.now()}`,
            role: 'assistant',
            content: response,
            attachments: [],
            createdAt: new Date().toISOString(),
          },
        ];
      });
    }
    streamingMsgIdRef.current = null;
    streamingTextRef.current = '';
  }, []);

  const onAlert = useCallback(({ approvalId }: { approvalId: string }) => {
    setSystemAlert(`Se ha requerido una aprobación humana (Approval ID: ${approvalId.slice(0, 8)}...). Un operador de backoffice revisará el caso.`);
  }, []);

  const onProblem = useCallback(({ code }: { code: string }) => {
    setIsTyping(false);
    setProblemAlert(`Se produjo un problema en la ejecución del backend (Código: ${code}).`);
  }, []);

  const realtime = useRealtime({
    enabled: true,
    onSnapshot,
    onStateChange,
    onDelta,
    onCompleted,
    onAlert,
    onProblem,
  });

  const handleConnect = useCallback(async (actorToUse = selectedActor) => {
    setIsConnecting(true);
    const res = await createDemoSession(actorToUse);
    if (res.ok) {
      const meRes = await getCurrentSession();
      if (meRes.ok && meRes.data) {
        setSessionRole(meRes.data.roles[0] || 'customer');
      }
      realtime.connect();
    } else {
      alert(`Error de autenticación demo: ${res.problem?.title || 'No se pudo crear la sesión'}`);
    }
    setIsConnecting(false);
  }, [selectedActor, realtime]);

  useEffect(() => {
    if (hasInitializedRef.current) return;
    hasInitializedRef.current = true;

    getDemoActors().then((res) => {
      if (res.ok && res.data) setActors(res.data);
    });
    handleConnect('demo-customer-1');
  }, [handleConnect]);

  const handleSendMessage = (text: string, attachmentIds: string[] = []) => {
    setProblemAlert(null);

    const userMessage: ConversationMessage = {
      messageId: `client-${Date.now()}`,
      role: 'customer',
      content: text || (attachmentIds.length > 0 ? `[${attachmentIds.length} adjunto(s)]` : ''),
      attachments: attachmentIds.map((id) => ({
        attachmentId: id,
        kind: 'image',
        mediaType: 'image/png',
        status: 'ready',
      })),
      createdAt: new Date().toISOString(),
    };

    setMessages((prev) => [...prev, userMessage]);

    setIsTyping(true);
    realtime.sendChat({
      clientMessageId: userMessage.messageId,
      text,
      threadId: currentThreadId || undefined,
      attachmentIds,
    });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', backgroundColor: 'var(--bg-color)' }}>
      <ModeSwitch
        actors={actors}
        selectedActor={selectedActor}
        onSelectActor={(id) => {
          setSelectedActor(id);
          handleConnect(id);
        }}
        onConnect={() => handleConnect()}
        isConnecting={isConnecting}
        isConnected={realtime.isConnected}
        sessionRole={sessionRole}
      />

      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <Chat
          messages={messages}
          onSendMessage={handleSendMessage}
          isTyping={isTyping}
          systemAlert={systemAlert}
          problemAlert={problemAlert}
          isRealMode={true}
        />
      </div>
    </div>
  );
}
